SELECT ST_XMin(ST_Expand(ST_MakeBox2D(ST_Point(0, 5), ST_Point(10, 20)), $1::float8, $2::float8)) AS xmin, ST_YMin(ST_Expand(ST_MakeBox2D(ST_Point(0, 5), ST_Point(10, 20)), $1::float8, $2::float8)) AS ymin, ST_ZMin(ST_Expand(ST_MakeBox2D(ST_Point(0, 5), ST_Point(10, 20)), $1::float8, $2::float8)) AS zmin, ST_XMax(ST_Expand(ST_MakeBox2D(ST_Point(0, 5), ST_Point(10, 20)), $1::float8, $2::float8)) AS xmax, ST_YMax(ST_Expand(ST_MakeBox2D(ST_Point(0, 5), ST_Point(10, 20)), $1::float8, $2::float8)) AS ymax, ST_ZMax(ST_Expand(ST_MakeBox2D(ST_Point(0, 5), ST_Point(10, 20)), $1::float8, $2::float8)) AS zmax
